<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import RelationsPanel from './RelationsPanel.vue'
import OwnerArtifactPanel from './OwnerArtifactPanel.vue'
import OwnerSourceNoteTaskPanel from './OwnerSourceNoteTaskPanel.vue'
import ProjectControlsPanel from './ProjectControlsPanel.vue'
import SourceCorrectionPanel from './SourceCorrectionPanel.vue'
import { VIEW_LABELS, type BackendController } from './use-backend.ts'
import { ARCHIVE_META, CONTENT_STATUS_LABELS, dashboardLabel, ownerLabel, visibleProjection } from './access-content-state.ts'
const props = defineProps<{ backend: BackendController; entryId: string }>()
const emit = defineEmits<{ 'request-login': [] }>()
const state = computed(() => props.backend.state)
const fallback = { title: '未开放档案', code: 'ARCHIVE / UNAVAILABLE', description: '此档案的信息功能尚未接入。', boundary: '没有可查看的角色记录。', view: null, fields: [] }
const meta = computed(() => props.entryId === 'demo-life' ? { title: '项目与作品', code: 'D10 / PROJECTS', description: '查看当前项目计划，明确暂停或恢复新增工作。', boundary: '已开始的操作仍可能需要核实，暂停不会把未知结果变为已取消。', view: null, fields: [] } : ARCHIVE_META[props.entryId] ?? fallback)
const currentProjection = computed(() => props.backend.runtimeReadable.value ? visibleProjection(state.value, props.entryId) : null)
const catalogue = computed(() => props.backend.runtimeReadable.value && state.value.auth === 'authenticated' && state.value.mode === 'same-origin' && state.value.workspace.status === 'ready' && state.value.workspace.data && `${state.value.workspace.data.namespace.bot}/${state.value.workspace.data.namespace.persona}` === state.value.scope ? state.value.workspace.data : null)
const capability = computed(() => meta.value.view ? catalogue.value?.views.find(view => view.view_type === meta.value.view) : null)
const count = computed(() => currentProjection.value?.data.candidates?.length ?? currentProjection.value?.data.sources?.length ?? null)
const loadStatus = computed(() => state.value.viewType === meta.value.view && meta.value.view ? state.value.view.status : 'idle')
const isLife = computed(() => props.entryId === 'demo-life')
const isContact = computed(() => props.entryId === 'demo-contact')
const isAccess = computed(() => props.entryId === 'demo-access')
const offline = computed(() => state.value.mode === 'offline')
const scope = ref(state.value.scope), correctingSourceId = ref('')
const statusCopy = computed(() => isContact.value ? 'HOLD · 联系操作暂停' : offline.value ? '未连接 · 零后端请求' : state.value.auth !== 'authenticated' ? '未获授权 · 等待会话核验' : !props.backend.runtimeReadable.value && (meta.value.view || isAccess.value || isLife.value) ? '角色读取暂不可用 · 请核验运行状态' : !props.backend.scopeValid.value ? '等待授权角色范围' : isAccess.value ? `可用功能 · ${CONTENT_STATUS_LABELS[state.value.workspace.status]}` : isLife.value ? '项目控制 · 当前计划待核验' : !meta.value.view ? 'UNAVAILABLE · 内容未接入' : capability.value?.status === 'unavailable' ? '当前功能不可用' : CONTENT_STATUS_LABELS[loadStatus.value])
const coverage = computed(() => currentProjection.value?.data.coverage === 'complete' ? '本次信息覆盖完整' : currentProjection.value?.coverage ? currentProjection.value.coverage.truncated ? '本次返回的信息已截断' : '本次返回的信息未截断' : '覆盖信息未公开')
const readDisabled = computed(() => !props.backend.canRead.value || state.value.view.pending || capability.value?.status === 'unavailable')
const showMessage = computed(() => meta.value.view && ['error', 'empty', 'disabled', 'unavailable', 'unauthorized', 'stale', 'partial', 'loading'].includes(loadStatus.value))
const safeCode = (code: string) => /^[A-Za-z0-9_.:-]{1,128}$/.test(code) ? code : '未公开可显示标识'
const routeLabel = (status: string) => ({ route_installed: '路由已安装', partial_route_installed: '路由部分安装', unavailable: '不可用' }[status] ?? '未核验')
async function load() { if (meta.value.view) await props.backend.readView(meta.value.view) }
function updateScope() { props.backend.setScope(scope.value) }
watch(() => props.entryId, entryId => { correctingSourceId.value = ''; props.backend.selectArchive(entryId) }, { immediate: true, flush: 'sync' })
watch(() => state.value.scope, value => { scope.value = value; correctingSourceId.value = '' })
watch(() => state.value.auth, auth => { if (auth !== 'authenticated') correctingSourceId.value = '' }, { flush: 'sync' })
watch(() => state.value.view.pending, pending => { if (pending) correctingSourceId.value = '' }, { flush: 'sync' })
onBeforeUnmount(() => props.backend.invalidateView())
</script>
<template>
  <section class="content-panel" :aria-label="meta.title + '的概览、字段信息和读取操作'">
    <header class="content-header"><div><p class="content-code">{{ meta.code }}</p><p class="content-intro">{{ meta.description }}</p></div><p class="connection-state" role="status" aria-live="polite"><span class="state-dot" :class="{ verified: state.auth === 'authenticated' && !isContact }" aria-hidden="true"></span>{{ statusCopy }}</p></header>
    <div class="dashboard-grid">
      <aside class="overview-column" aria-labelledby="archive-overview-title">
        <p class="section-kicker">01 / OVERVIEW</p><h3 id="archive-overview-title">档案概览</h3>
        <dl class="overview-facts"><div><dt>当前角色范围</dt><dd>{{ state.scope || '尚未选择' }}</dd></div><div><dt>读取来源</dt><dd>{{ offline ? '后端未连接' : state.auth === 'authenticated' ? '当前账户可查看的信息' : '会话尚未核验' }}</dd></div><div><dt>内容状态</dt><dd>{{ isContact ? 'HOLD' : isLife ? '按实际项目核验' : !meta.view && !isAccess ? '未接入' : isAccess ? CONTENT_STATUS_LABELS[state.workspace.status] : CONTENT_STATUS_LABELS[loadStatus] }}</dd></div><div v-if="currentProjection"><dt>本次返回记录</dt><dd>{{ count }} 条</dd></div><div v-if="currentProjection"><dt>访问版本</dt><dd>{{ currentProjection.access_generation }}</dd></div></dl>
        <p class="boundary-note">{{ meta.boundary }}</p>
        <div class="auth-summary"><h4>身份与权限</h4><dl><div><dt>AstrBot 后台</dt><dd>{{ dashboardLabel(state) }}</dd></div><div><dt>所有者会话</dt><dd>{{ ownerLabel(state) }}</dd></div></dl><button class="text-action" @click="emit('request-login')">{{ state.auth === 'authenticated' ? '管理访问与退出' : '查看访问验证' }} <span class="arrow-icon" aria-hidden="true"></span></button></div>
      </aside>
      <div class="data-column" aria-labelledby="archive-data-title" :aria-busy="!!state.view.pending || !!state.workspace.pending">
        <p class="section-kicker">02 / INFORMATION</p><h3 id="archive-data-title">{{ isAccess ? '可用功能' : '方案与来源信息' }}</h3>
        <template v-if="isAccess">
          <div v-if="catalogue" class="capability-summary">
            <dl class="catalogue-facts"><div><dt>命名空间</dt><dd>{{ catalogue.namespace.bot }}/{{ catalogue.namespace.persona }}</dd></div><div><dt>访问版本</dt><dd>{{ catalogue.access_generation }}</dd></div></dl>
            <ul v-if="catalogue.views.length" class="capability-list"><li v-for="view in catalogue.views" :key="view.view_type"><div><strong>{{ VIEW_LABELS[view.view_type] }}</strong><small>{{ view.view_type }}</small></div><span class="capability-status" :class="{ available: view.status === 'available' }">{{ view.status === 'available' ? '可读取' : '不可用' }}</span></li></ul><p v-else class="empty-copy">当前授权目录没有返回公开视图。</p>
            <div v-if="catalogue.view_diagnostics.length" class="catalogue-detail"><h4>视图读取状态</h4><dl><div v-for="diagnostic in catalogue.view_diagnostics" :key="diagnostic.view_type"><dt>{{ VIEW_LABELS[diagnostic.view_type] }}</dt><dd>{{ CONTENT_STATUS_LABELS[diagnostic.read_status] }}{{ diagnostic.coverage === 'partial' ? ' · 部分覆盖' : diagnostic.coverage === 'complete' ? ' · 完整覆盖' : '' }}</dd></div></dl></div>
            <div v-if="catalogue.command_routes.length" class="catalogue-detail"><h4>接口状态</h4><dl><div v-for="route in catalogue.command_routes" :key="route.action"><dt>{{ safeCode(route.action) }}</dt><dd>{{ routeLabel(route.status) }}</dd></div></dl><p class="boundary-note">功能入口存在不代表操作已执行，也不会解除主动联系 HOLD。</p></div>
            <p v-if="Object.keys(catalogue.unavailable_domains).length" class="boundary-note">部分领域暂不可用。这里只显示当前账户可查看的功能与状态。</p>
            <RelationsPanel v-if="catalogue.views.some(view => view.view_type === 'relations' && view.status === 'available')" :backend="backend"/>
          </div>
          <div v-else class="empty-state"><span aria-hidden="true">—</span><h4>{{ offline ? '可用功能尚未连接' : state.auth !== 'authenticated' ? '先核验所有者会话' : '尚未读取可用功能' }}</h4><p>当前账户可用的功能将在读取后显示。</p></div>
          <p v-if="state.workspace.status !== 'ready' && state.workspace.message" class="content-message" :role="state.workspace.status === 'error' ? 'alert' : 'status'">{{ state.workspace.message }}</p>
        </template>
        <template v-else-if="meta.view">
          <div v-if="currentProjection && count" class="record-list"><p class="record-meta">第 {{ backend.viewPaging.page }} 页 · 本次返回 {{ count }} 条 · {{ coverage }}</p>
            <article v-for="candidate in currentProjection.data.candidates" :key="candidate.plan_id + ':' + candidate.version" class="record-card"><h4>{{ candidate.plan_id }}</h4><dl><div><dt>方案标识 <small>plan_id</small></dt><dd>{{ candidate.plan_id }}</dd></div><div><dt>版本 <small>version</small></dt><dd>{{ candidate.version }}</dd></div><div><dt>作者资格 <small>authored</small></dt><dd>{{ candidate.authored ? '是（true）' : '否（false）' }}</dd></div><div><dt>组成数量 <small>block_count</small></dt><dd>{{ candidate.block_count }}</dd></div><div><dt>价值规则数量 <small>value_rule_count</small></dt><dd>{{ candidate.value_rule_count }}</dd></div></dl></article>
            <article v-for="source in currentProjection.data.sources" :key="source.source_id" class="record-card"><h4>{{ source.source_id }}</h4><dl><div><dt>来源标识 <small>source_id</small></dt><dd>{{ source.source_id }}</dd></div><div><dt>来源类型 <small>source_kind</small></dt><dd>{{ source.source_kind }}</dd></div><div><dt>断言状态 <small>assertion_status</small></dt><dd>{{ source.assertion_status }}</dd></div><div><dt>记录时间 <small>recorded_at</small></dt><dd>{{ source.recorded_at }}</dd></div><div><dt>资格记录 <small>qualification</small></dt><dd>未记录 · not_recorded</dd></div></dl><button class="text-action" :disabled="!backend.canRead.value" @click="correctingSourceId = source.source_id">查看更正依据</button></article>
            <p v-if="currentProjection.coverage?.truncated || currentProjection.next_cursor" class="boundary-note">当前结果有截断或后续游标；返回条数不能视为全部记录。可使用下一页继续读取，页面只保留当前页。</p>
          </div>
          <div v-else class="empty-state"><span aria-hidden="true">{{ loadStatus === 'loading' ? '·' : '—' }}</span><h4>{{ offline ? '真实内容尚未连接' : state.auth !== 'authenticated' ? '角色内容尚未授权' : loadStatus === 'empty' ? '本次读取没有记录' : loadStatus === 'loading' ? '正在读取角色信息' : '尚无可查看的角色记录' }}</h4><p>{{ offline ? '离线界面只展示结构与字段说明。' : state.auth !== 'authenticated' ? '先完成会话核验，再读取当前范围。' : '读取结果、覆盖状态与错误会按后端实际返回显示。' }}</p></div>
          <p v-if="showMessage" class="content-message" :role="loadStatus === 'error' ? 'alert' : 'status'" aria-live="polite">{{ state.view.message }}</p>
          <div v-if="!currentProjection" class="field-catalogue"><h4>可查看的五项信息</h4><dl><div v-for="field in meta.fields" :key="field.key"><dt>{{ field.label }}</dt><dd>{{ field.key }}</dd></div></dl><p class="boundary-note">以上仅为信息类型说明，尚未读取真实记录。</p></div>
        </template>
        <template v-else-if="isLife"><ProjectControlsPanel :backend="backend"/><OwnerArtifactPanel :backend="backend"/><OwnerSourceNoteTaskPanel :backend="backend"/></template>
        <div v-else class="empty-state"><span aria-hidden="true">{{ isContact ? 'Ⅱ' : '—' }}</span><h4>{{ isContact ? '联系操作保持 HOLD' : '生活内容尚未接入' }}</h4><p>{{ meta.boundary }}</p></div>
        <SourceCorrectionPanel v-if="meta.view === 'd06.memory_sources.v1' && backend.canRead.value" :backend="backend" :source-id="correctingSourceId" @select-source="correctingSourceId = $event"/>
      </div>
      <aside class="operations-column" aria-labelledby="archive-operations-title">
        <p class="section-kicker">03 / OPERATIONS</p><h3 id="archive-operations-title">{{ isContact ? '联系操作' : isLife ? '读取与控制' : '只读操作' }}</h3>
        <div v-if="isContact" class="hold-state"><p>发送归属待确认</p><button class="read-action" disabled aria-describedby="contact-hold-reason">发送联系 · HOLD</button><p id="contact-hold-reason">不会调用发送接口，也不创建发送任务。</p></div>
        <template v-else>
          <button v-if="state.auth !== 'authenticated'" class="read-action" @click="emit('request-login')">{{ offline ? '查看接入要求' : '核验访问会话' }} <span class="arrow-icon forward" aria-hidden="true"></span></button>
          <form v-if="state.auth === 'authenticated'" class="scope-form" @submit.prevent="updateScope"><label for="content-role-scope">授权角色范围</label><input id="content-role-scope" v-model="scope" placeholder="bot/persona" maxlength="192" autocomplete="off" spellcheck="false" :disabled="state.busy" aria-describedby="content-scope-hint"><p id="content-scope-hint" class="field-hint">按当前安装记录填写。后端仍需核验此范围。</p><button class="text-action" :disabled="state.busy || !scope.trim()" type="submit">应用范围</button></form>
          <template v-if="meta.view || isAccess || isLife"><button class="text-action" :disabled="!backend.management.canRuntime.value" @click="backend.management.checkRuntime">{{ backend.management.active.runtime ? '正在核验运行状态…' : '核验运行状态' }}</button><p class="field-hint" role="status">{{ backend.management.state.runtime.data ? `runtime_stage：${backend.management.state.runtime.data.stage} · reason_code：${backend.management.state.runtime.data.reason}` : '实际运行阶段尚未读取。' }}运行就绪只允许发起请求，角色权限仍由后端逐次核验。</p></template>
          <button class="read-action" :disabled="!backend.canRead.value || state.workspace.pending" @click="backend.openWorkspace">{{ state.workspace.pending ? '正在读取目录…' : catalogue ? '重新读取可用功能' : '读取可用功能' }}</button>
          <button v-if="meta.view" class="read-action" :disabled="readDisabled" @click="load">{{ state.view.pending ? '正在读取信息…' : currentProjection ? '从第一页刷新档案' : ['error', 'stale', 'partial', 'unavailable', 'loading'].includes(loadStatus) ? '重试读取档案信息' : '发起授权只读读取' }}</button>
          <button v-if="meta.view && currentProjection?.next_cursor" class="read-action" :disabled="!backend.canNextView.value" @click="backend.nextView">读取下一页</button>
          <p v-if="offline" class="field-hint">后端未连接，所有读取按钮停用。离线演示不会调用 API。</p><p v-else-if="state.auth !== 'authenticated'" class="field-hint">会话未核验，不显示保护内容。</p><p v-else-if="!backend.scopeValid.value" class="field-hint">需要有效的 bot/persona 才能发起只读请求。</p>
          <p v-if="state.workspace.status !== 'ready' && state.workspace.message && !isAccess" class="content-message" :role="state.workspace.status === 'error' ? 'alert' : 'status'">{{ state.workspace.message }}</p>
          <p v-if="state.error && !showMessage && state.workspace.status !== 'error'" class="content-message" role="alert">{{ state.error }}</p>
        </template>
        <div class="operation-boundary"><h4>操作边界</h4><p>仅显示当前账户有权查看的信息。过期、退出或切换角色后，旧内容会清空。</p><p>关闭详情会保留已核验会话。退出所有者会话请到访问面板。</p></div>
      </aside>
    </div>
  </section>
</template>
<style scoped>
.content-panel{font-size:13px;line-height:1.8;color:var(--ink,#354348);width:100%;min-width:0}.content-header{display:flex;gap:28px;align-items:flex-start;justify-content:space-between;padding:0 0 22px;border-bottom:1px solid var(--line,#cbd6d8)}.content-code,.section-kicker{font-size:9px;letter-spacing:.14em;color:var(--muted,#617177);margin:0 0 9px}.content-intro{margin:0;max-width:550px;font-size:14px}.connection-state{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--muted,#617177);margin:3px 0;flex:none;max-width:270px;overflow-wrap:anywhere}.state-dot{width:6px;height:6px;flex:none;border-radius:50%;background:#9ba9a2}.state-dot.verified{background:#82985d}.dashboard-grid{display:grid;grid-template-columns:minmax(170px,.75fr) minmax(0,1.5fr) minmax(185px,.8fr);gap:32px;padding-top:26px}.dashboard-grid>aside,.data-column{min-width:0}.dashboard-grid h3{font-size:17px;font-weight:450;letter-spacing:.015em;margin:0 0 22px}.dashboard-grid h4{font-size:12px;font-weight:500;margin:0 0 12px}.overview-facts,.auth-summary dl,.field-catalogue dl,.record-card dl,.catalogue-detail dl,.catalogue-facts{margin:0}.overview-facts>div{padding:10px 0;border-bottom:1px solid var(--line,#cbd6d8)}dt{font-size:11px;color:var(--muted,#617177)}dd{margin:3px 0 0;overflow-wrap:anywhere;font-size:12px}.boundary-note,.field-hint{font-size:10px;color:var(--muted,#617177);line-height:1.8;margin:15px 0}.auth-summary{margin-top:28px;padding-top:18px;border-top:1px solid var(--line,#cbd6d8)}.auth-summary dl>div,.field-catalogue dl>div,.catalogue-detail dl>div,.catalogue-facts>div{display:flex;justify-content:space-between;gap:14px;padding:8px 0;border-bottom:1px solid var(--line,#cbd6d8)}.auth-summary dd,.field-catalogue dd,.catalogue-detail dd,.catalogue-facts dd{margin:0;text-align:right;font-size:10px}.text-action{font-size:11px;min-height:44px;display:flex;gap:12px;align-items:center;padding:8px 0;text-align:left;color:var(--ink,#354348)}.read-action{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:11px 13px;font-size:11px;min-height:44px;background:#e1e8d5;border:1px solid #c1cbb1;border-radius:3px;margin:0 0 12px;text-align:left;color:var(--ink,#354348)}.read-action:disabled{background:#edf0ed;border-color:#d5dcd2;color:#728078;cursor:default}.scope-form{margin:0 0 24px}.scope-form label{display:block;font-size:11px;margin-bottom:7px}.scope-form input{box-sizing:border-box;width:100%;min-height:44px;border:1px solid #bdcacc;border-radius:3px;background:#f9fbf8;padding:10px;font:inherit;font-size:12px;color:#354348}.scope-form .field-hint{margin:7px 0 0}.operation-boundary{border-top:1px solid var(--line,#cbd6d8);margin-top:25px;padding-top:20px}.operation-boundary p,.hold-state p{font-size:10px;color:var(--muted,#617177);line-height:1.8;margin:7px 0 14px}.empty-state{background:#f1f4ed;border:1px solid #dde4d7;border-radius:4px;padding:22px 20px;margin:0 0 20px}.empty-state>span{font-size:22px;color:#8b9c87}.empty-state h4{font-size:14px;font-weight:450;margin:7px 0}.empty-state p,.empty-copy{font-size:11px;color:var(--muted,#617177);margin:6px 0}.field-catalogue{padding:18px 0 0}.field-catalogue h4{font-size:11px}.record-meta{font-size:10px;color:var(--muted,#617177);margin:0 0 16px}.record-card{border:1px solid #d0dac9;border-radius:4px;background:#fafbf6;padding:18px;margin:0 0 16px}.record-card h4{font-size:14px;font-weight:450;overflow-wrap:anywhere;margin:0 0 13px}.record-card dl>div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;border-top:1px solid #e0e6da;padding:9px 0}.record-card dt{font-size:11px;color:var(--ink,#354348)}.record-card dt small{display:block;font-size:9px;color:var(--muted,#617177)}.record-card dd{text-align:right;font-size:11px;margin:0;align-self:center}.content-message{font-size:11px;padding:12px 13px;line-height:1.8;color:#79533e;background:#f4eee5;border-radius:3px;overflow-wrap:anywhere}.capability-list{list-style:none;margin:18px 0 0;padding:0}.capability-list li{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--line,#cbd6d8)}.capability-list strong{display:block;font-size:12px;font-weight:450}.capability-list small{display:block;font-size:9px;color:var(--muted,#617177);overflow-wrap:anywhere}.capability-status{font-size:10px;flex:none;color:var(--muted,#617177)}.capability-status.available{color:#657a48}.catalogue-detail{margin-top:24px}.catalogue-detail dt{overflow-wrap:anywhere;min-width:0}.arrow-icon{display:inline-block;width:7px;height:7px;border-top:1px solid currentColor;border-right:1px solid currentColor}.arrow-icon.forward{transform:rotate(45deg)}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid #587020;outline-offset:3px}@media(max-width:950px){.dashboard-grid{grid-template-columns:minmax(150px,.7fr) minmax(0,1.4fr);gap:26px}.operations-column{grid-column:1 / -1;border-top:1px solid var(--line,#cbd6d8);padding-top:20px}.operations-column .scope-form{max-width:350px}.operations-column .read-action{max-width:350px}}@media(max-width:640px){.content-header{display:block;padding-bottom:18px}.connection-state{margin-top:15px;max-width:none}.dashboard-grid{grid-template-columns:1fr;gap:24px;padding-top:22px}.overview-column{border-bottom:1px solid var(--line,#cbd6d8);padding-bottom:20px}.overview-facts{display:grid;grid-template-columns:1fr 1fr;gap:0 15px}.dashboard-grid h3{margin-bottom:16px}.auth-summary{margin-top:16px;padding-top:16px}.operations-column{grid-column:auto}.operations-column .scope-form,.operations-column .read-action{max-width:none}.record-card{padding:16px}}
</style>
